initial_feature_files.seat-pool.mjs:
export class SeatPool {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 0) {
      throw new RangeError("capacity must be a nonnegative integer");
    }
    this.remaining = capacity;
  }

  available() {
    return this.remaining;
  }
}

initial_feature_files.seat-pool.test.mjs:
import assert from "node:assert/strict";
import test from "node:test";
import { SeatPool } from "./seat-pool.mjs";

test("a new pool exposes its capacity", () => {
  const pool = new SeatPool(5);

  const available = pool.available();

  assert.equal(available, 5);
});

test("an empty pool is valid", () => {
  const pool = new SeatPool(0);

  const available = pool.available();

  assert.equal(available, 0);
});

test("invalid capacities are rejected", () => {
  for (const capacity of [-1, 1.5, NaN]) {
    assert.throws(() => new SeatPool(capacity), RangeError);
  }
});

execution_setup.independent_grader_source:
import assert from "node:assert/strict";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";

const { SeatPool } = await import(pathToFileURL(resolve(process.argv[2])));
const pool = new SeatPool(5);
assert.equal(pool.reserve(2), true);
assert.equal(pool.available(), 3);
assert.equal(pool.reserve(4), false);
assert.equal(pool.available(), 3);
assert.equal(pool.reserve(3), true);
assert.equal(pool.available(), 0);
assert.equal(pool.reserve(1), false);
assert.equal(pool.available(), 0);
for (const count of [0, -1, 1.5, NaN, Infinity, "2", null, undefined]) {
  const fresh = new SeatPool(5);
  assert.throws(() => fresh.reserve(count), RangeError);
  assert.equal(fresh.available(), 5);
}
for (const capacity of [-1, 1.5, NaN]) {
  assert.throws(() => new SeatPool(capacity), RangeError);
}
assert.equal(new SeatPool(0).available(), 0);
console.log("PASS: accepted, declined, invalid, sequential and exact-capacity reservations; state preservation and existing constructors.");

