}

initial_files.booking.test.mjs:
import test from "node:test";
import assert from "node:assert/strict";
import { createBooking } from "./booking.mjs";

test("booking records preserve the payment amount", () => {
  const booking = createBooking("b-1", 12000);

  assert.deepEqual(booking, { id: "b-1", paidCents: 12000, status: "confirmed", refundedCents: 0 });
});

